        let (t, _) = type_run(&mut pet, t, 4, 12, 3, 0.06);
        let (_, f) = idle(&mut pet, t, (4, 15), SIT_AFTER + 0.5);
        assert_eq!(f.pose, PetGlyphId::PetSitFront, "fixture: the stare");
